def start_trial(page: Page, arena: str, args) -> tuple[dict, int, int]:
    wait_scene_ready(page)
    page.loading = False
    snap = page.snapshot()
    if snap.get("state") == "fighting" and not snap.get("overworld"):
        raise SystemExit("页面已有试炼在进行，已停止自动循环。")
    basis = None
    for _ in range(4):
        basis = page.js("window.__lw.bot.calibrateAsync()", timeout=10)
        if basis:
            break
        time.sleep(3)
    if not basis:
        raise SystemExit("移动标定未通过，已停止；未请求试炼开局。")
    log(f"移动标定：{json.dumps(basis)}")
    mark_trial(page, arena)
    expression = "window.__lw.startReadiness(%s)" % json.dumps(arena)
    wait_readiness(page, expression, "试炼动作及 GPU 预热")
    st = (page.snapshot().get("trial") or {}).get("status") or {}
    remaining = st.get("remaining")
    if type(remaining) is not int or remaining < 0 or not (st.get("tier") or {}).get("next"):
        raise SystemExit("试炼次数或重数未确认，已停止；未请求试炼开局。")
    if args.practice_only and remaining > 0:
        raise SystemExit("今天还有有奖次数，练习模式已停止；未请求试炼开局。")
    if remaining == 0 and not (args.practice_ok or args.practice_only):
        raise SystemExit("今日有奖次数用完，已停止；未请求试炼开局。")
    want = want_tier(st, args)
    if choose_tier(page, want) != want:
        raise SystemExit("重数未选定，已停止；未请求试炼开局。")
    # 检查和真实 start 在同一 JS 调用内，防止两个 CDP 往返之间又出现 loading / 状态切换。
    # start 返回 false 时只重试检查；一旦真实 start 成功，绝不再次调用它。
    deadline = time.monotonic() + 60
    while time.monotonic() < deadline:
        accepted = page.js("""(() => {
const lw = window.__lw;
lw.needStatus = true; lw.needReady = true; lw.startArena = %s;
try {
  const s = lw.combat.stats(), st = s.trial?.status;
  if (s.trial?.tier?.chosen !== %d || st?.remaining !== %d) return false;
  return !!lw.runtime.startTownCombat(lw.startArena);
} finally { lw.needStatus = false; lw.needReady = false; }
})()""" % (json.dumps(arena), want, remaining))
        if accepted:
            snap = page.snapshot()
            chosen = (snap.get("trial") or {}).get("tier", {}).get("run")
            if snap.get("state") != "fighting" or snap.get("overworld") or snap.get("arena") != arena or chosen != want:
                raise SystemExit("开局状态发生变化，已停止后续局，请检查页面。")
            log(f"本局重数 {chosen}（开局前有奖剩余 {remaining}，加载与举盾检查已通过）")
            return st, want, chosen
        check = page.js("window.__lw.lastStartCheck || " + expression) or {}
        if not check.get("ready"):
            log("开局检查未通过：" + "、".join(check.get("reasons") or ["动作未接受"]))
        time.sleep(2)
    raise SystemExit("开局检查未通过，已停止；未请求试炼开局。")

