function beginTrialRun(){const token=++trial.token,previous=trial.ending;Object.assign(trial,{run:null,rewards:[],cultivation:0,cultivationPercent:0,swordBox:null,grade:null,anomaly:null,firstClear:null,tierResult:null,session:null});if(!options.trialRequest||instanceArena()||questMode)return;
  const session={token,run:null,nextWave:0,confirmed:-1,closing:false,error:'',pending:0};trial.session=session;
  const startBody={operationId:trialOp('start'),carry:3,arena:arena.id,tier:runTier};
  const opening=Promise.resolve(previous).then(()=>trialCall('start',startBody)).then(data=>{
    if(!data?.run){session.error='opening';if(token===trial.token)say('试炼开局记录未确认 · 请重新连接后挑战',4,'bad');return;}
    session.run={...data.run};if(token!==trial.token)return;trial.run=session.run;applyTrialScale();
    if(data.run.carry>0){potions.carry+=data.run.carry;waveStartPotions.carry+=data.run.carry;}
    const s=data.status;say(data.run.rewarded?`有奖试炼 · 今日第 ${s?.used??'?'} / ${s?.limit??3} 次${data.run.carry?` · 带入回灵丹 ${data.run.carry} 颗（用掉才扣）`:''}`:'今日有奖次数已用完 · 本局为练习，不发奖励',3.2,data.run.rewarded?'good':'');});
  session.queue=opening;
}

