function command(id,gated=false){if(id==='share')return shareReport();if(id==='interact'&&interactMechanic())return true;if(id==='tierDown'||id==='tierUp')return pickTier(id==='tierUp'?1:-1);if(['interact','map','gait'].includes(id))return options.onCommonAction?.(id)||false;if(id==='pause'&&enabled()&&(!active||state==='fighting'||localPaused))return setPaused(!localPaused);if(id==='pause')return false;if(id==='start')return localPaused?setPaused(false):start({questMode:options.getEncounter?options.getEncounter()?.kind==='quest':questMode});if(id==='restart')return start({questMode:options.getEncounter?options.getEncounter()?.kind==='quest':questMode});if(id==='retry')return retryWave();if(id==='stop'){if(!active)return false;stop();return true;}preloadReference();if(!canAct()||paused())return false;
  if(id==='hpPotion'||id==='manaPotion')return cooldown[id]>0?false:drink(id);
  if(id==='lock'){const next=pickNearbyLockTarget(lockTargets(),target,getActor().root.position,time-lastTabAt<1.5&&target===lastTabTarget);
    selectCombatTarget(next,'manual');lastTabAt=time;lastTabTarget=next;return true;}
  if(id==='volley'||id==='pierce')return castPierce();
  if(id==='ult')return useSkill({key:'ult',name:'大招',cast:0},castUltimate);
  if(id==='moon')return useSkill({key:'moon',name:'月影',cast:0,gcd:false},castMoon);
  if(id==='art')return castArt();
  if(id==='nextArt'){artIndex=(artIndex+1)%arts().length;return true;}
  if(id==='fan')return castFan();
  if(id==='swords'||id==='bind')return castGiantSword();
  if(/^slot[1-9]\d*$/.test(id))return castSlot(Number(id.slice(4)));
  if(id==='shieldWheel')return toggleShieldWheel();
  if(noSwords()&&['draw','wheel'].includes(id))return refuseSwords();
  if(id==='blink')return options.onBlink?.()||false;
  if(id==='draw'){environment.toggleSwords();return true;}
  if(id==='wheel'){environment.setSwordWheel(!environment.stats().swords?.wheel?.enabled);return true;}
  if(airborne()&&id==='attack')return castPierce();
  if(airborne()){say('御空中无法施展近战');return false;}
  if(id==='guard'){setGuard(!guard);return true;}
  if(action?.kind==='charge'&&id==='dodge'){cancelPress();}

  if(id==='attack'&&action?.kind==='attack'&&action.combo<3){queued=true;action.queueUntil=action.time+.42;return true;}
  if(action&&!(id==='dodge'&&(action.kind==='cast'||action.time>action.duration*.55)))return false;
  if(cooldown[id]>0)return false;
  if(id==='fire')id='spell';
  if(id==='spell'){if(cooldown.spell>0)return false;
    if(gated!==true)return useSkill(artSpec('火弹'),()=>command('spell',true));
    if(mana<manaCost(15)){say('灵力不足',1.4,'bad');return false;}mana-=manaCost(15);cooldown.spell=RULES.arts['火弹'].cool;
    aimActor(24);guard=false;const aimTarget=targetReady(target)&&distance(target.root.position,getActor().root.position)<=24?target:null;
    action={kind:'spell',time:0,duration:.65,contact:.24,hit:false,aimTarget,aimPosition:aimTarget?.root.position.clone(),aimVelocity:new T.Vector3(),aimDirection:facing()};reference.playHero('thrust');return true;
  }
  if(id==='dodge'){cancelCast('dodged');
    const dodgeCost=25*(1-slotEffect('duel_dodge_chance')/100);if(stamina<dodgeCost){say('身法尚未恢复',1.4,'bad');return false;}stamina-=dodgeCost;cooldown.dodge=.7;guard=false;queued=false;reportCast({k:'use',key:'dodge'});
    const input=getInput(),p=getActor().root.position;let dx=input.x,dz=input.z;
    if(Math.hypot(dx,dz)<.1){dx=-Math.sin(getActor().root.rotation.y);dz=-Math.cos(getActor().root.rotation.y);}
    const length=Math.hypot(dx,dz);action={kind:id,time:0,duration:.52,dx:dx/length,dz:dz/length};getActor().stopControl();metrics.dodges++;
    const local=new T.Vector3(action.dx,0,action.dz).applyAxisAngle(up,-getActor().root.rotation.y);action.clip=local.z>.5?'dodgeF':local.z<-.5?'dodgeB':local.x>0?'dodgeL':'dodgeR';action.duration=reference.meta(action.clip).duration;reference.playHero(action.clip,{direction:new T.Vector3(action.dx,0,action.dz),distance:action.clip==='dodgeF'?3.6:action.clip==='dodgeB'?3:3.1});burst(p.clone().add(new T.Vector3(0,.4,0)),0x7cdbe5,1.0,.38);return true;
  }
  if(id==='thrust'||id==='heavy'){if(gated!==true)return useSkill({key:'m:'+id,name:id==='heavy'?'重击':'突刺',cast:0},()=>command(id,true));if(stamina<20){say('身法尚未恢复',1.4,'bad');return false;}stamina-=20;aimActor(id==='thrust'?7:4);guard=false;const m=reference.meta(id);action={...m,kind:'attack',clip:id,time:0,combo:3,contact:(m.hit[0][0]+m.hit[0][1])*.5};reference.playHero(id,{target:target?.root});return true;}
  if(id==='attack'){if(castState.casting)return false;combo=0;beginAttack();return true;}return false;
}

functions.applyLevelScale:
function applyLevelScale(scale){if(!scale)return;
  for(const e of enemies){if(!e.inWave||e.hp<=0||e.levelScaled||e.custom)continue;
    const k=e.kind.boss?scale.boss:ELITE_ROLES.has(e.role)?(scale.elite||scale.normal):scale.normal;if(!k)continue;
    const fraction=e.hp/e.maxHp;e.maxHp=Math.round(e.baseHp*k.hp);e.hp=Math.max(1,Math.round(e.maxHp*fraction));
    e.levelDamage=k.damage;e.levelScaled=true;e.label.querySelector('span').textContent=`Lv.${k.level} ${e.kind.name}`;}}
